Item.method_code:
const { itemTypeName, itemId } = options;
const isNew = ArasModules.item.getChanges(itemTypeName, itemId)
	? ArasModules.item.isNew(itemTypeName, itemId)
	: window.item.getAttribute('action') === 'add';
const isCurrentVersion =
	aras.getItemProperty(window.item, 'is_current') === '1';

if (isNew || isCurrentVersion) {
	return {
		hidden: true
	};
}

const majorVersion = aras.getItemProperty(window.item, 'major_rev');
const generation = aras.getItemProperty(window.item, 'generation');

const versionLabel = aras.getResource('', 'version.indicator');
const label = `${versionLabel} ${majorVersion}.${generation}`;

const cssClass = 'aras-toolbar__title non-current-version-indicator';

return {
	type: 'text',
	label,
	cssClass,
};
